watch([() => session.ready, () => session.authenticated, () => route.path], () => {
  if (!session.ready) return
  const isAuth = ['/login','/register'].includes(route.path)
  if (!session.authenticated && !isAuth) void router.replace({path:'/login',query:{next:route.fullPath}})
  else if (session.authenticated && isAuth) {
    const next = String(route.query.next ?? '/')
    void router.replace(next.startsWith('/') && !next.startsWith('//') && !next.includes('\\') && !/^\/(login|register)([/?#]|$)/.test(next) ? next : '/')
  }
}, { immediate:true })

